template<typename BASE_T, typename VALUE_T> inline uint64_t napot_match(const BASE_T& base_in, const VALUE_T& value_in)
{
    uint64_t base = (uint64_t)(logic<64>(base_in));
    uint64_t value = (uint64_t)(logic<64>(value_in));
    bool is_valid_napot = ((base & (base + 1)) == 0);
    if (!is_valid_napot) return 0;
    uint64_t mask = ~(base & ~(base + 1));
    return ((value & mask) == (base & mask)) ? 1 : 0;
}

template<typename SCONTEXT_T, typename SSELECT_T, typename SBYTEMASK_T, typename SVALUE_T, typename FLAG_T> inline uint64_t match_scontext(const SCONTEXT_T& scontext_in, const SSELECT_T& sselect_in, const SBYTEMASK_T& sbytemask_in, const SVALUE_T& svalue_in, const FLAG_T& flag_in)
{
    uint64_t scontext = (uint64_t)(logic<32>(scontext_in));
    uint64_t sselect = (uint64_t)(logic<2>(sselect_in));
    uint64_t sbytemask = (uint64_t)(logic<4>(sbytemask_in));
    uint64_t svalue = (uint64_t)(logic<32>(svalue_in));
    bool flag = (bool)(logic<1>(flag_in));
    if (sselect != 1) return 0;
    int max_bytes = flag ? 4 : 2;
    for (int b = 0; b < max_bytes; ++b) {
        if (!((sbytemask >> b) & 1u) && (((scontext >> (8*b)) & 0xffu) != ((svalue >> (8*b)) & 0xffu))) return 0;
    }
    return 1;
}

inline constexpr uint64_t range_check(uint64_t base, uint64_t len, uint64_t address)
{
    return (address >= base && address < (base + len)) ? 1ull : 0ull;
}

inline constexpr uint64_t is_inside_nonidempotent_regions(cva6_cfg_t Cfg, uint64_t address)
{
    for (unsigned k = 0; k < Cfg.NrNonIdempotentRules; ++k) {
        if (range_check(Cfg.NonIdempotentAddrBase[k], Cfg.NonIdempotentLength[k], address)) return 1ull;
    }
    return 0ull;
}

inline constexpr uint64_t is_inside_execute_regions(cva6_cfg_t Cfg, uint64_t address)
{
    if (Cfg.NrExecuteRegionRules == 0) return 1ull;
    for (unsigned k = 0; k < Cfg.NrExecuteRegionRules; ++k) {
        if (range_check(Cfg.ExecuteRegionAddrBase[k], Cfg.ExecuteRegionLength[k], address)) return 1ull;
    }
    return 0ull;
}

inline constexpr uint64_t is_inside_cacheable_regions(cva6_cfg_t Cfg, uint64_t address)
{
    for (unsigned k = 0; k < Cfg.NrCachedRegionRules; ++k) {
        if (range_check(Cfg.CachedRegionAddrBase[k], Cfg.CachedRegionLength[k], address)) return 1ull;
    }
    return 0ull;
}
